#!/usr/bin/env node
// Rebuilds the theme showcase from the folders in themes/.
//   - README.md           (between <!-- THEMES:START --> and <!-- THEMES:END -->)
//   - themes/README.md    (between the same markers)
//   - themes/<name>/README.md  (only if missing or still auto-generated)
//
// Each theme lives in themes/<name>/<name>.json and describes itself with a "meta" block:
//   "meta": { "name": "...", "description": "...", "author": "github-username",
//             "tags": ["dark"], "added": "YYYY-MM-DD" }
// Drop a preview.png / .jpg / .webp / .gif in the folder to show it. Without one, a placeholder is used.
//
// Run: node scripts/build-gallery.js   (GitHub Actions runs it for you on every push to themes/)
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const THEMES = path.join(ROOT, 'themes');
const PLACEHOLDER = 'docs/assets/theme-placeholder.png';
const COLUMNS = 3;          // themes per row in the main README
const SHOWCASE_LIMIT = 6;   // newest N themes shown in the main README
const AUTO_MARK = '<!-- auto-generated by scripts/build-gallery.js: delete this line to write your own README -->';

const esc = s => String(s).replace(/[<>&"]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' }[c]));
const titleCase = s => s.split('-').map(w => w[0].toUpperCase() + w.slice(1)).join(' ');

function loadThemes() {
  const list = [];
  for (const dir of fs.readdirSync(THEMES, { withFileTypes: true })) {
    if (!dir.isDirectory()) continue;
    const slug = dir.name;
    const file = path.join(THEMES, slug, `${slug}.json`);
    if (!fs.existsSync(file)) { console.warn(`skip ${slug}: no ${slug}.json`); continue; }
    let data;
    try { data = JSON.parse(fs.readFileSync(file, 'utf8')); } catch { console.warn(`skip ${slug}: invalid JSON`); continue; }
    const m = data.meta || {};
    const s = data.settings || {};
    const preview = ['png', 'jpg', 'jpeg', 'webp', 'gif'].map(ext => `preview.${ext}`)
      .find(f => fs.existsSync(path.join(THEMES, slug, f)));
    list.push({
      slug,
      name: m.name || data.profiles?.[0]?.name || titleCase(slug),
      description: m.description || '',
      author: m.author || '',
      tags: Array.isArray(m.tags) ? m.tags : [],
      added: m.added || '1970-01-01',
      preview,
      palette: ['background', 'surface', 'text', 'accent', 'title2'].map(k => s[k]).filter(Boolean),
    });
  }
  // Newest first, then alphabetical.
  return list.sort((a, b) => b.added.localeCompare(a.added) || a.name.localeCompare(b.name));
}

function img(t, fromRoot) {
  if (t.preview) return fromRoot ? `themes/${t.slug}/${t.preview}` : `${t.slug}/${t.preview}`;
  return fromRoot ? PLACEHOLDER : `../${PLACEHOLDER}`;
}

function replaceBetween(file, block) {
  const text = fs.readFileSync(file, 'utf8');
  const re = /(<!-- THEMES:START -->)[\s\S]*?(<!-- THEMES:END -->)/;
  if (!re.test(text)) { console.warn(`no THEMES markers in ${path.relative(ROOT, file)}`); return false; }
  const next = text.replace(re, `$1\n${block}\n$2`);
  if (next !== text) { fs.writeFileSync(file, next); return true; }
  return false;
}

function mainShowcase(themes) {
  const shown = themes.slice(0, SHOWCASE_LIMIT);
  const width = Math.floor(100 / COLUMNS);
  let rows = '';
  for (let i = 0; i < shown.length; i += COLUMNS) {
    const cells = shown.slice(i, i + COLUMNS).map(t => `    <td width="${width}%" align="center" valign="top">
      <a href="themes/${t.slug}/"><img src="${img(t, true)}" alt="${esc(t.name)}" width="100%"></a>
      <br><b><a href="themes/${t.slug}/">${esc(t.name)}</a></b>
      <br><sub>${t.tags.map(esc).join(' · ')}</sub>
    </td>`).join('\n');
    rows += `  <tr>\n${cells}\n  </tr>\n`;
  }
  const more = themes.length > shown.length ? ` · <a href="themes/">+${themes.length - shown.length} more</a>` : '';
  return `<p align="center"><sub><b>${themes.length}</b> theme${themes.length === 1 ? '' : 's'} and counting${more}</sub></p>

<table>
${rows}</table>`;
}

function galleryTable(themes) {
  const rows = themes.map(t =>
    `| <a href="${t.slug}/"><img src="${img(t, false)}" width="240" alt="${esc(t.name)}"></a> | [**${esc(t.name)}**](${t.slug}/)<br><sub>${esc(t.description)}</sub> | ${t.tags.map(x => '`' + x + '`').join(' ')} | ${t.author ? `[@${t.author}](https://github.com/${t.author})` : '—'} |`);
  return `| Preview | Theme | Tags | Author |\n|:---:|---|---|---|\n${rows.join('\n')}`;
}

function themeReadme(t) {
  return `${AUTO_MARK}
# ${t.name}

${t.description ? `> ${t.description}\n` : ''}
<img src="${t.preview || `../../${PLACEHOLDER}`}" alt="${esc(t.name)} preview" width="100%">

| | |
|---|---|
| **Author** | ${t.author ? `[@${t.author}](https://github.com/${t.author})` : '—'} |
| **Tags** | ${t.tags.map(x => '`' + x + '`').join(' ') || '—'} |
| **Palette** | ${t.palette.map(c => '`' + c + '`').join(' ')} |
| **Added** | ${t.added === '1970-01-01' ? '—' : t.added} |

## Install

1. Download [\`${t.slug}.json\`](${t.slug}.json) (open it, then click **Download raw file**).
2. In **YouTube Theme Studio**, go to **Export → Import backup** and pick the file.
3. The theme applies right away and is saved under your profiles.
`;
}

const themes = loadThemes();
let changed = [];
if (replaceBetween(path.join(ROOT, 'README.md'), mainShowcase(themes))) changed.push('README.md');
if (replaceBetween(path.join(THEMES, 'README.md'), galleryTable(themes))) changed.push('themes/README.md');
for (const t of themes) {
  const file = path.join(THEMES, t.slug, 'README.md');
  if (fs.existsSync(file) && !fs.readFileSync(file, 'utf8').startsWith(AUTO_MARK)) continue; // hand-written, leave it
  const next = themeReadme(t);
  if (!fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== next) { fs.writeFileSync(file, next); changed.push(`themes/${t.slug}/README.md`); }
}
console.log(`${themes.length} themes. ${changed.length ? 'Updated:\n  ' + changed.join('\n  ') : 'Nothing to update.'}`);
